// Draws the exploration map from the user's entries.
// Terrain is generated by code (value noise + marching squares), the same for every visit.
// Each region (career direction) clears the fog around it; entries become roads, outposts, builds.
window.JV = window.JV || {};
(function () {
  const W = 1600, H = 1600, START = { x: 800, y: 1040 };
  const C = { line: "#B4BCC6", blue: "#2F5D8C", orange: "#B4561A", violet: "#6B4FA8", teal: "#2C7A6B", gray: "#8A877F", ink: "#1E2329", muted: "#5E6670", bg: "#F2F4F7" };
  const NS = "http://www.w3.org/2000/svg";

  // ---- seeded randomness ----
  function hash(str) { let h = 2166136261; for (const c of String(str)) { h ^= c.charCodeAt(0); h = Math.imul(h, 16777619); } return (h >>> 0) / 4294967296; }
  function rng(seed) { let s = seed >>> 0; return () => ((s = Math.imul(s ^ (s >>> 15), 2246822507) ^ Math.imul(s ^ (s >>> 13), 3266489909)) >>> 0) / 4294967296; }

  // ---- terrain contours (computed once) ----
  let terrainPath = null;
  function terrain() {
    if (terrainPath) return terrainPath;
    const N = 80, cell = W / N, r = rng(7), bumps = [];
    for (let i = 0; i < 22; i++) bumps.push({ x: r() * W, y: r() * H, s: 120 + r() * 260, a: r() * 2.2 - 0.9 });
    const z = [];
    for (let j = 0; j <= N; j++) { z[j] = []; for (let i = 0; i <= N; i++) {
      const x = i * cell, y = j * cell; let v = 0.12 * Math.sin(x / 90) * Math.cos(y / 130);
      for (const b of bumps) v += b.a * Math.exp(-((x - b.x) ** 2 + (y - b.y) ** 2) / (2 * b.s * b.s));
      z[j][i] = v; } }
    let d = "";
    const lerp = (a, b, l) => (l - a) / (b - a || 1e-9);
    for (let l = -0.8; l <= 1.4; l += 0.16) {
      for (let j = 0; j < N; j++) for (let i = 0; i < N; i++) {
        const a = z[j][i], b = z[j][i + 1], c = z[j + 1][i + 1], e = z[j + 1][i];
        const x = i * cell, y = j * cell, pts = [];
        if ((a < l) !== (b < l)) pts.push([x + cell * lerp(a, b, l), y]);
        if ((b < l) !== (c < l)) pts.push([x + cell, y + cell * lerp(b, c, l)]);
        if ((e < l) !== (c < l)) pts.push([x + cell * lerp(e, c, l), y + cell]);
        if ((a < l) !== (e < l)) pts.push([x, y + cell * lerp(a, e, l)]);
        if (pts.length >= 2) d += `M${pts[0][0].toFixed(0)},${pts[0][1].toFixed(0)}L${pts[1][0].toFixed(0)},${pts[1][1].toFixed(0)}`;
        if (pts.length === 4) d += `M${pts[2][0].toFixed(0)},${pts[2][1].toFixed(0)}L${pts[3][0].toFixed(0)},${pts[3][1].toFixed(0)}`;
      }
    }
    return (terrainPath = d);
  }

  // ---- layout ----
  const ANG = [0, -48, 48, -92, 92, -24, 24, -70, 70, -120, 120];
  function hub(slot) {
    const a = (ANG[slot % ANG.length] - 90) * Math.PI / 180, dist = 300 + 150 * Math.floor(slot / ANG.length) + (slot % 2 ? 40 : 0);
    return { x: START.x + Math.cos(a) * dist, y: START.y + Math.sin(a) * dist };
  }
  // Spread entries evenly around the hub (golden angle), so markers never pile up.
  function place(e, h, R, i, n) {
    const a = i * 2.39996 + hash(e.id) * 0.6, d = R * (0.32 + 0.55 * Math.sqrt((i + 1) / Math.max(n, 1)));
    return { x: h.x + Math.cos(a) * d, y: h.y + Math.sin(a) * d };
  }

  const el = (tag, attrs, text) => { const n = document.createElementNS(NS, tag); for (const k in attrs) n.setAttribute(k, attrs[k]); if (text != null) n.textContent = text; return n; };

  JV.renderMap = function (svg) {
    const { regions, entries } = JV.store.state, t = JV.t();
    svg.textContent = "";
    svg.setAttribute("aria-label", t.mapTitle);

    // compute regions geometry
    const geo = regions.map(r => {
      const list = entries.filter(e => e.regionId === r.id);
      return { r, h: hub(r.slot), R: 90 + 26 * Math.sqrt(list.length), list };
    });

    // fit the view to what has been explored, matched to the element's shape
    const pts = [START, ...geo.flatMap(g => [{ x: g.h.x - g.R, y: g.h.y - g.R }, { x: g.h.x + g.R, y: g.h.y + g.R }])];
    let x0 = Math.min(...pts.map(p => p.x)) - 160, x1 = Math.max(...pts.map(p => p.x)) + 160;
    let y0 = Math.min(...pts.map(p => p.y)) - 160, y1 = Math.max(...pts.map(p => p.y)) + 120;
    const box = svg.getBoundingClientRect(), aspect = (box.width || 4) / (box.height || 3);
    let vw = Math.max(x1 - x0, 520), vh = Math.max(y1 - y0, 420);
    if (vw / vh < aspect) vw = vh * aspect; else vh = vw / aspect;
    const cx = (x0 + x1) / 2, cy = (y0 + y1) / 2;
    svg.setAttribute("viewBox", `${cx - vw / 2} ${cy - vh / 2} ${vw} ${vh}`);
    svg.setAttribute("preserveAspectRatio", "xMidYMid slice");

    const defs = el("defs", {});
    const blur = el("filter", { id: "jvsoft", x: "-50%", y: "-50%", width: "200%", height: "200%" });
    blur.appendChild(el("feGaussianBlur", { stdDeviation: "28" }));
    const mask = el("mask", { id: "jvfog", maskUnits: "userSpaceOnUse", x: 0, y: 0, width: W, height: H });
    mask.appendChild(el("rect", { x: 0, y: 0, width: W, height: H, fill: "white" }));
    const holes = el("g", { filter: "url(#jvsoft)", fill: "black" });
    holes.appendChild(el("circle", { cx: START.x, cy: START.y, r: 90 }));
    geo.forEach(g => {
      holes.appendChild(el("circle", { cx: g.h.x, cy: g.h.y, r: g.R + 30 }));
      holes.appendChild(el("path", { d: `M${START.x},${START.y} Q${(START.x + g.h.x) / 2 + 40},${(START.y + g.h.y) / 2} ${g.h.x},${g.h.y}`, stroke: "black", "stroke-width": 110, fill: "none" }));
    });
    mask.appendChild(holes); defs.append(blur, mask); svg.appendChild(defs);

    svg.appendChild(el("rect", { x: 0, y: 0, width: W, height: H, fill: C.bg }));
    svg.appendChild(el("path", { d: terrain(), stroke: C.line, "stroke-width": 1.2, fill: "none" }));
    svg.appendChild(el("rect", { x: 0, y: 0, width: W, height: H, fill: C.bg, opacity: 0.93, mask: "url(#jvfog)" }));

    const today = new Date().toDateString();
    const g = el("g", {});
    geo.forEach(G => {
      g.appendChild(el("path", { d: `M${START.x},${START.y} Q${(START.x + G.h.x) / 2 + 40},${(START.y + G.h.y) / 2} ${G.h.x},${G.h.y}`, stroke: C.blue, "stroke-width": 2.4, fill: "none", "stroke-linecap": "round", opacity: 0.85 }));
      G.list.forEach((e, i) => {
        const p = place(e, G.h, G.R, i, G.list.length), isToday = new Date(e.date).toDateString() === today;
        if (e.type === "apply") {
          g.appendChild(el("path", { d: `M${G.h.x},${G.h.y} Q${(G.h.x + p.x) / 2 + 18},${(G.h.y + p.y) / 2 - 10} ${p.x},${p.y}`, stroke: C.blue, "stroke-width": 2, fill: "none", "stroke-linecap": "round" }));
        }
        // Each marker is a focusable group, so hover, tap or keyboard can open its card.
        const m = el("g", { class: "hit", tabindex: 0, role: "button", "data-eid": e.id, "aria-label": e.title || e.type });
        m.appendChild(el("circle", { cx: p.x, cy: p.y, r: 20, fill: "transparent" }));
        if (isToday) m.appendChild(el("circle", { class: "ring", cx: p.x, cy: p.y, r: 22, fill: "none", stroke: C.blue, "stroke-width": 1.4, opacity: 0.45 }));
        if (e.type === "apply") {
          m.appendChild(el("circle", { cx: p.x, cy: p.y, r: 5, fill: C.blue }));
        } else if (e.type === "connect") {
          m.appendChild(el("circle", { cx: p.x, cy: p.y, r: 8, fill: C.bg, stroke: C.orange, "stroke-width": 2.4 }));
        } else if (e.type === "make") {
          m.appendChild(el("rect", { x: p.x - 7, y: p.y - 7, width: 14, height: 14, rx: 2, fill: C.violet }));
        } else if (e.type === "learn") {
          m.appendChild(el("path", { d: `M${p.x},${p.y - 10} L${p.x + 8},${p.y + 7} L${p.x - 8},${p.y + 7} Z`, fill: "none", stroke: C.teal, "stroke-width": 2.2, "stroke-linejoin": "round" }));
        } else {
          m.appendChild(el("path", { d: `M${p.x - 9},${p.y + 6} L${p.x},${p.y - 8} L${p.x + 9},${p.y + 6} Z`, fill: C.gray }));
        }
        g.appendChild(m);
      });
      g.appendChild(el("circle", { cx: G.h.x, cy: G.h.y, r: 4, fill: C.ink }));
      g.appendChild(el("text", { x: G.h.x, y: G.h.y - G.R - 14, "text-anchor": "middle", fill: C.ink, "font-size": 22, "letter-spacing": 2, "font-family": "inherit" }, G.r.name));
    });
    g.appendChild(el("path", { d: `M${START.x - 12},${START.y + 12} L${START.x},${START.y - 12} L${START.x + 12},${START.y + 12} Z`, fill: C.ink }));
    g.appendChild(el("text", { x: START.x, y: START.y + 42, "text-anchor": "middle", fill: C.muted, "font-size": 18, "font-family": "inherit" }, t.start));
    const fy = Math.min(...[START.y, ...geo.map(x => x.h.y - x.R)]) - 90;
    g.appendChild(el("text", { x: START.x - 260, y: fy, fill: C.muted, "font-size": 18, "letter-spacing": 2, "font-family": "inherit" }, t.fog));
    svg.appendChild(g);
    bindTips(svg);
  };

  // ---- entry card (tooltip) ----
  const esc = v => String(v ?? "").replace(/[&<>"']/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c]);
  JV.entryCard = function (e, withEdit) {
    const t = JV.t(), date = t.dateFmt(new Date(e.date));
    const meta = [t.types[e.type], e.roleType && t.roles[e.roleType], e.seniority && t.seniorityL[e.seniority], date].filter(Boolean).join(" · ");
    let html = `<div class="tip-title">${esc(e.title || [e.role, e.company].filter(Boolean).join(" · "))}</div><div class="tip-meta">${esc(meta)}</div>`;
    if (e.type === "apply") {
      const f = e.focus ? JV.DIMS.filter(d => e.focus[d] > 0).sort((a, b) => e.focus[b] - e.focus[a]) : [];
      if (f.length) html += `<div><div class="tip-meta">${esc(t.focusLabel)}</div>` + f.map(d => `<div class="fbar"><span>${esc(t.dimShort[d])}</span><span class="track"><i style="width:${Math.round(e.focus[d] / 3 * 100)}%"></i></span><span>${e.focus[d]}</span></div>`).join("") + `</div>`;
      if (e.skills?.length) html += `<div><div class="tip-meta">${esc(t.skillsLabel)}</div><div class="chips">${e.skills.map(k => `<span>${esc(k)}</span>`).join("")}</div></div>`;
      if (!f.length && !e.skills?.length) html += `<div class="tip-meta">${esc(t.noProfile)}</div>`;
    }
    if (e.insight) html += `<div>${esc(e.insight)}</div>`;
    if (withEdit) html += `<div><button class="btn" type="button" data-edit="${esc(e.id)}">${esc(t.openRecord)}</button></div>`;
    return html;
  };

  let pinned = null;
  function bindTips(svg) {
    const tip = document.getElementById("tip"), wrap = svg.parentElement;
    const show = (node, pin) => {
      const e = JV.store.state.entries.find(x => x.id === node.dataset.eid); if (!e) return;
      tip.innerHTML = JV.entryCard(e, pin); tip.hidden = false; tip.classList.toggle("pinned", !!pin);
      tip.querySelector("[data-edit]")?.addEventListener("click", ev => { ev.stopPropagation(); pinned = null; tip.hidden = true; JV.openEntry(e.id); });
      const r = node.getBoundingClientRect(), w = wrap.getBoundingClientRect();
      const tw = tip.offsetWidth, th = tip.offsetHeight;
      let x = r.left - w.left + r.width / 2 - tw / 2, y = r.top - w.top - th - 10;
      if (y < 8) y = r.bottom - w.top + 10;
      x = Math.max(8, Math.min(x, w.width - tw - 8));
      tip.style.left = x + "px"; tip.style.top = Math.min(y, w.height - th - 8) + "px";
    };
    const hide = () => { if (!pinned) tip.hidden = true; };
    svg.querySelectorAll(".hit").forEach(n => {
      n.addEventListener("pointerenter", ev => { if (ev.pointerType === "mouse" && !pinned) show(n); });
      n.addEventListener("pointerleave", hide);
      n.addEventListener("focus", () => show(n));
      n.addEventListener("blur", hide);
      n.addEventListener("click", ev => { ev.stopPropagation(); pinned = pinned === n.dataset.eid ? null : n.dataset.eid; if (pinned) show(n, true); else tip.hidden = true; });
      n.addEventListener("keydown", ev => { if (ev.key === "Enter" || ev.key === " ") { ev.preventDefault(); n.dispatchEvent(new MouseEvent("click")); } if (ev.key === "Escape") { pinned = null; tip.hidden = true; } });
    });
    svg.onclick = () => { pinned = null; tip.hidden = true; };
  }
})();
